function exportSTL(){if(!modelRoot.children.length){setStatus('Build or upload artwork first.',true);return;}try{const blob=stlExporter.parse(modelRoot,{binary:true});downloadBlob(new Blob([blob],{type:'model/stl'}),'LEDSign-print-ready.stl');setStatus('STL exported. Check bed fit, shell unions and mounting details in your slicer.');}catch(e){setStatus('STL export failed: '+e.message,true);}}
function exportGLB(){if(!modelRoot.children.length){setStatus('Build or upload artwork first.',true);return;}try{gltfExporter.parse(modelRoot,result=>{downloadBlob(new Blob([result],{type:'model/gltf-binary'}),'LEDSign-preview.glb');setStatus('GLB exported.');},err=>setStatus('GLB export failed: '+err.message,true),{binary:true,onlyVisible:true});}catch(e){setStatus('GLB export failed: '+e.message,true);}}
function resetApp(){sourceData=null;sourceSvgText='';sourceLabel='';wireRoutes=[];wireDraft=[];wireHoles=[];wireMode='';letterOffsets.clear();selectedLetterGroups.clear();letterEditMode=false;letterDragState=null;if(controls)controls.enabled=true;fontBuffer=null;parsedFont=null;helperVisibility.clear();disposeGroup(modelRoot);disposeGroup(edgeRoot);disposeGroup(guideRoot);for(const [id,v]of Object.entries({artWidth:400,artHeight:200,wallHeight:18,wallThickness:2,floorThickness:2,ledgeDistance:3,ledgeWidth:3,ledgeHeight:2,supportAngle:45,diffuserThickness:2,ledWidth:9,ledPhysicalWidth:8,ledPhysicalHeight:16,ledClearance:.75,smoothness:6,backplaneMargin:18,backplaneThickness:3,tileWidth:250,tileHeight:250,joinDepth:7,joinWidth:24,bedWidth:256,bedHeight:256}))$(id).value=v;$('buildStyle').value='letters';$('ledProduct').value='neon8x16_12';$('closedBack').checked=true;$('ledgeEnabled').checked=true;$('backplaneEnabled').checked=true;$('backplaneStyle').value='rounded';$('joinStyle').value='dovetail';$('mountStyle').value='keyholes';$('embossIds').checked=true;$('cornerMode').value='bevel';$('featureEdges').checked=true;$('metalColor').value='#8995a7';$('signText').value='LED SIGN';$('fontChoice').value='roboto';$('bedPreset').value='256,256';$('svgFile').value='';$('fontFile').value='';$('emptyState').hidden=false;$('helperBar').hidden=true;updateRequestedSize();$('modelName').textContent='Your channel will appear here';$('pathLength').textContent='—';$('artSize').textContent='—';$('partCount').textContent='—';$('diffuserFit').textContent='—';applyLedProfile();toggleFields();setStatus('Reset. Upload an SVG or switch to Text to start.');}
function bindUI(){document.querySelectorAll('[data-input-tab]').forEach(b=>b.addEventListener('click',()=>setInputTab(b.dataset.inputTab)));$('svgFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{await parseSvgText(await f.text(),f.name);}catch(err){setStatus('SVG load failed: '+err.message,true);}});$('dropZone').addEventListener('dragover',e=>{e.preventDefault();$('dropZone').classList.add('dragover');});$('dropZone').addEventListener('dragleave',()=>$('dropZone').classList.remove('dragover'));$('dropZone').addEventListener('drop',async e=>{e.preventDefault();$('dropZone').classList.remove('dragover');const f=e.dataTransfer.files?.[0];if(!f)return;if(!f.name.toLowerCase().endsWith('.svg')){setStatus('Drop an SVG file to begin.',true);return;}try{sourceSvgText=await f.text();await parseSvgText(sourceSvgText,f.name);}catch(err){setStatus('SVG load failed: '+err.message,true);}});$('sampleSign').addEventListener('click',sample);$('canvasSample').addEventListener('click',sample);$('buildText').addEventListener('click',async()=>{try{await buildText();}catch(e){setStatus('Text-to-outline failed: '+e.message,true);}});$('fontFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{fontBuffer=await f.arrayBuffer();parsedFont=null;$('fontChoice').value='custom';sourceSvgText='';await buildText();}catch(err){setStatus('Font loading failed: '+err.message,true);}});$('fontChoice').addEventListener('change',()=>{parsedFont=null;if(activeInput==='text')buildText().catch(e=>setStatus(e.message,true));});$('backplaneEnabled').addEventListener('change',scheduleRebuild);$('ledProduct').addEventListener('change',()=>{applyLedProfile();scheduleRebuild();});$('toggleLetterEdit').addEventListener('click',()=>setLetterEditMode(!letterEditMode));$('alignCenter').addEventListener('click',()=>alignSelectedLetters('center'));$('alignLeft').addEventListener('click',()=>alignSelectedLetters('left'));$('alignRight').addEventListener('click',()=>alignSelectedLetters('right'));$('alignTop').addEventListener('click',()=>alignSelectedLetters('top'));$('alignBottom').addEventListener('click',()=>alignSelectedLetters('bottom'));$('markWireRoute').addEventListener('click',()=>enterWireMode('route'));$('markWireHole').addEventListener('click',()=>enterWireMode('hole'));$('finishWireRoute').addEventListener('click',finishWireRoute);$('undoWire').addEventListener('click',undoWireEdit);$('clearWire').addEventListener('click',clearWireEdits);const live=['buildStyle','artWidth','artHeight','wallHeight','wallThickness','closedBack','floorThickness','ledgeEnabled','ledgeDistance','ledgeWidth','ledgeHeight','supportAngle','diffuserThickness','ledWidth','ledPhysicalWidth','ledPhysicalHeight','ledClearance','cornerMode','smoothness','backplaneStyle','backplaneMargin','backplaneThickness','tileWidth','tileHeight','joinStyle','joinDepth','joinWidth','mountStyle','embossIds','bedWidth','bedHeight'];for(const id of live)$(id).addEventListener('input',()=>{if(id==='smoothness')$('smoothValue').textContent=$('smoothness').value;if(['ledPhysicalWidth','ledClearance'].includes(id))updateLedChannelWidth();if(['artWidth','artHeight'].includes(id))updateRequestedSize();toggleFields();scheduleRebuild();});$('buildStyle').addEventListener('change',()=>{toggleFields();scheduleRebuild();});$('bedPreset').addEventListener('change',()=>{if($('bedPreset').value!=='custom'){const p=$('bedPreset').value.split(',');$('bedWidth').value=p[0];$('bedHeight').value=p[1];scheduleRebuild();}});$('metalColor').addEventListener('input',()=>modelRoot.traverse(o=>{if(o.isMesh&&o.userData.kind!=='backplane'&&o.userData.kind!=='mount'&&o.userData.kind!=='emboss')o.material.color.set($('metalColor').value);}));$('featureEdges').addEventListener('change',rebuildEdges);$('toggleHelper').addEventListener('click',toggleHelper);$('downloadSTL').addEventListener('click',exportSTL);$('downloadGLB').addEventListener('click',exportGLB);$('reset').addEventListener('click',resetApp);$('frontView').addEventListener('click',()=>setCamera('front'));$('topView').addEventListener('click',()=>setCamera('top'));$('isoView').addEventListener('click',()=>setCamera('iso'));$('fitView').addEventListener('click',fitCamera);renderer.domElement.addEventListener('pointerdown',beginLetterPointer,true);renderer.domElement.addEventListener('pointermove',moveLetterPointer);renderer.domElement.addEventListener('pointerup',endLetterPointer,true);renderer.domElement.addEventListener('pointercancel',endLetterPointer,true);renderer.domElement.addEventListener('click',e=>{if(handleWireCanvasClick(e)||letterEditMode)return;selectedWallHit(e);});}
initViewer();bindUI();applyLedProfile();toggleFields();
